import io,os,base64,unittest,zipfile
from pathlib import Path
from PIL import Image
from pypdf import PdfReader
from workspace_plugin import interchange as api
class FinalPDF(unittest.TestCase):
 def test_pdf_cell_blocks_lists_inline_images_and_docx(self):
  out=Path(os.environ['HWS_SMOKE_OUTPUT']);pic=Image.new('RGBA',(2,1));pic.putdata([(20,60,100,255),(220,40,80,255)]);raw=io.BytesIO();pic.save(raw,format='PNG');src='data:image/png;base64,'+base64.b64encode(raw.getvalue()).decode();html='<table><tr><td><p>Before <strong>bold</strong></p><ol start="3"><li>Alpha</li><li>Beta<ul><li>Nested</li></ul></li></ol><p>Tail</p><p><img src="'+src+'" alt="Sample"/>After image</p></td><td><p>Adjacent</p></td></tr></table>';doc={'title':'Cell block preservation','content':html};pdf=api.export_document(doc,'pdf');(out/'cell-blocks.pdf').write_bytes(pdf);reader=PdfReader(io.BytesIO(pdf));text='\n'.join(p.extract_text() for p in reader.pages);(out/'pdf-text.txt').write_text(text);self.assertIn('3. Alpha',text);self.assertIn('4. Beta',text);self.assertIn('- Nested',text);self.assertNotIn('Beforebold3.',text);words=['Before','bold','Alpha','Beta','Nested','Tail','After image','Adjacent'];self.assertEqual(sorted(words,key=text.index),words);pictures=[im for p in reader.pages for im in p.images];self.assertEqual(len(pictures),1);self.assertEqual(pictures[0].image.convert('RGBA').tobytes(),pic.tobytes());fonts=str([f.get_object().get('/BaseFont') for p in reader.pages for f in p['/Resources']['/Font'].get_object().values()]);self.assertIn('Bold',fonts);docx=api.export_document(doc,'docx');(out/'cell-blocks.docx').write_bytes(docx);parsed=api.import_file('cell-blocks.docx',docx);self.assertIn('<ol start="3">',parsed['content']);self.assertIn('Nested',parsed['content'])
